const removeIds = new Set(Object.values(REMOVE).flat().map(([id]) => id))
const trivia = JSON.parse(readFileSync(PATH, "utf8"))
let removed = 0
let rewritten = 0
for (const [cat, questions] of Object.entries(trivia.categories)) {
  trivia.categories[cat] = questions.filter((q) => {
    if (removeIds.has(q.id)) { removed++; return false }
    const fix = REWRITE[q.id]
    if (fix && q.q === fix.from) {
      const { from, ...fields } = fix
      const before = JSON.stringify(q)
      Object.assign(q, fields)
      if (JSON.stringify(q) !== before) rewritten++
    }
    return true
  })
}
writeFileSync(PATH, JSON.stringify(trivia, null, 2) + "\n")
console.log(`Removed ${removed}, rewrote ${rewritten}.`)
